dashboard.definition:
{
  "title": "Statewide Exercise - Modern Dashboard Studio",
  "description": "Modern Dashboard Studio JSON conversion of statewide_exercise_v1.xml with tabbed layout, refreshed searches, token filters, drilldown detail panels, and enterprise network monitoring visuals.",
  "inputs": {
    "input_time_range": {
      "type": "input.timerange",
      "title": "Time Range",
      "options": {
        "token": "time_tok",
        "defaultValue": "-24h@h,now"
      }
    },
    "input_refresh_rate": {
      "type": "input.dropdown",
      "title": "Refresh",
      "options": {
        "token": "refresh_tok",
        "defaultValue": "60s",
        "items": [
          {
            "label": "60 seconds",
            "value": "60s"
          },
          {
            "label": "5 minutes",
            "value": "300s"
          },
          {
            "label": "15 minutes",
            "value": "900s"
          }
        ]
      }
    },
    "input_client_type": {
      "type": "input.dropdown",
      "title": "Client Type",
      "options": {
        "token": "client_type_tok",
        "defaultValue": "*",
        "items": [
          {
            "label": "All clients",
            "value": "*"
          },
          {
            "label": "Wireless",
            "value": "Wireless"
          },
          {
            "label": "Wired",
            "value": "Wired"
          }
        ]
      }
    },
    "input_site_filter": {
      "type": "input.text",
      "title": "Site Filter",
      "options": {
        "token": "site_tok",
        "defaultValue": "*"
      }
    },
    "input_close_issue": {
      "type": "input.button",
      "title": "",
      "options": {
        "label": "Close Details"
      },
      "eventHandlers": [
        {
          "type": "drilldown.setToken",
          "options": {
            "tokens": [
              {
                "token": "selected_issue",
                "value": ""
              },
              {
                "token": "selected_issue_priority",
                "value": ""
              }
            ]
          }
        }
      ],
      "containerOptions": {
        "visibility": {
          "showConditions": [
            "condition_issue_selected"
          ]
        }
      }
    }
  },
  "defaults": {
    "dataSources": {
      "global": {
        "options": {
          "refresh": "$refresh_tok$",
          "refreshType": "delay"
        }
      },
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$time_tok.earliest$",
            "latest": "$time_tok.latest$"
          }
        }
      },
      "ds.spl2": {
        "options": {
          "queryParameters": {
            "earliest": "$time_tok.earliest$",
            "latest": "$time_tok.latest$"
          }
        }
      }
    },
    "visualizations": {
      "global": {
        "showProgressBar": true,
        "showLastUpdated": true
      }
    },
    "tokens": {
      "default": {
        "selected_issue": {
          "value": ""
        },
        "selected_issue_priority": {
          "value": ""
        },
        "selected_client": {
          "value": ""
        },
        "site_tok": {
          "value": "*"
        },
        "client_type_tok": {
          "value": "*"
        },
        "refresh_tok": {
          "value": "60s"
        }
      }
    }
  },
  "visualizations": {
    "viz_header_overview": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## General Overview\nMonitor statewide wired and wireless client health across all sites. Use the filters above to narrow client views by site or connection type.",
        "backgroundColor": "#ffffff",
        "fontColor": "#111827",
        "fontSize": "small"
      },
      "showProgressBar": false,
      "showLastUpdated": false
    },
    "viz_header_exec": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## Overall Health Summary - Network Devices\nExecutive view of device health, inventory, and active Catalyst Center issues across the statewide environment.",
        "backgroundColor": "#ffffff",
        "fontColor": "#111827",
        "fontSize": "small"
      },
      "showProgressBar": false,
      "showLastUpdated": false
    },
    "viz_header_client": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## Client Summary\nComprehensive client health, distribution, activity, and top-client details for operational troubleshooting.",
        "backgroundColor": "#ffffff",
        "fontColor": "#111827",
        "fontSize": "small"
      },
      "showProgressBar": false,
      "showLastUpdated": false
    },
    "viz_header_about": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## About This Dashboard\nSource, design, and operational notes for the statewide network exercise dashboard.",
        "backgroundColor": "#ffffff",
        "fontColor": "#111827",
        "fontSize": "small"
      },
      "showProgressBar": false,
      "showLastUpdated": false
    },
    "viz_ov_wireless_health": {
      "type": "splunk.singlevalue",
      "title": "Wireless Health",
      "description": "Wireless client health with threshold-colored sparkline.",
      "dataSources": {
        "primary": "ds_kpi_wireless_health"
      },
      "options": {
        "majorValue": "> primary | seriesByName('Wireless Health') | lastPoint()",
        "majorColor": "> majorValue | rangeValue(healthColorRange)",
        "majorFontSize": 38,
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "showSparklineTooltip": true,
        "sparklineStrokeColor": "> majorValue | rangeValue(healthColorRange)",
        "sparklineAreaColor": "> majorValue | rangeValue(healthColorRange)",
        "trendDisplay": "percent",
        "showTrendIndicator": true,
        "unit": "%",
        "shouldAbbreviateMajorValue": true,
        "shouldAbbreviateTrendValue": true,
        "backgroundColor": "#ffffff"
      },
      "context": {
        "healthColorRange": [
          {
            "to": 80,
            "value": "#dc2626"
          },
          {
            "from": 80,
            "to": 95,
            "value": "#eab308"
          },
          {
            "from": 95,
            "value": "#16a34a"
          }
        ]
      }
    },
    "viz_ov_wireless_clients": {
      "type": "splunk.singlevalue",
      "title": "Wireless Clients",
      "description": "Total wireless clients currently connected.",
      "dataSources": {
        "primary": "ds_kpi_wireless_total"
      },
      "options": {
        "majorValue": "> primary | seriesByName('Wireless Clients') | lastPoint()",
        "majorColor": "#2563eb",
        "majorFontSize": 38,
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "showSparklineTooltip": true,
        "sparklineStrokeColor": "#2563eb",
        "sparklineAreaColor": "rgba(37,99,235,0.18)",
        "trendDisplay": "percent",
        "showTrendIndicator": true,
        "shouldAbbreviateMajorValue": true,
        "shouldAbbreviateTrendValue": true,
        "backgroundColor": "#ffffff"
      }
    },
    "viz_ov_wireless_healthy": {
      "type": "splunk.singlevalue",
      "title": "Healthy Wireless Clients",
      "description": "Wireless clients currently in healthy status.",
      "dataSources": {
        "primary": "ds_wireless_trend_24h"
      },
      "options": {
        "majorValue": "> primary | seriesByName('Healthy') | lastPoint()",
        "majorColor": "#16a34a",
        "majorFontSize": 38,
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "showSparklineTooltip": true,
        "sparklineStrokeColor": "#2563eb",
        "sparklineAreaColor": "rgba(37,99,235,0.18)",
        "trendDisplay": "percent",
        "showTrendIndicator": true,
        "shouldAbbreviateMajorValue": true,
        "shouldAbbreviateTrendValue": true,
        "backgroundColor": "#ffffff"
      }
    },
    "viz_ov_wired_health": {
      "type": "splunk.singlevalue",
      "title": "Wired Health",
      "description": "Wired client health with threshold-colored sparkline.",
      "dataSources": {
        "primary": "ds_kpi_wired_health"
      },
      "options": {
        "majorValue": "> primary | seriesByName('Wired Health') | lastPoint()",
        "majorColor": "> majorValue | rangeValue(healthColorRange)",
        "majorFontSize": 38,
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "showSparklineTooltip": true,
        "sparklineStrokeColor": "> majorValue | rangeValue(healthColorRange)",
        "sparklineAreaColor": "> majorValue | rangeValue(healthColorRange)",
        "trendDisplay": "percent",
        "showTrendIndicator": true,
        "unit": "%",
        "shouldAbbreviateMajorValue": true,
        "shouldAbbreviateTrendValue": true,
        "backgroundColor": "#ffffff"
      },
      "context": {
        "healthColorRange": [
          {
            "to": 80,
            "value": "#dc2626"
          },
          {
            "from": 80,
            "to": 95,
            "value": "#eab308"
          },
          {
            "from": 95,
            "value": "#16a34a"
          }
        ]
      }
    },
    "viz_ov_wired_clients": {
      "type": "splunk.singlevalue",
      "title": "Wired Clients",
      "description": "Total wired clients currently connected.",
      "dataSources": {
        "primary": "ds_kpi_wired_total"
      },
      "options": {
        "majorValue": "> primary | seriesByName('Wired Clients') | lastPoint()",
        "majorColor": "#7c3aed",
        "majorFontSize": 38,
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "showSparklineTooltip": true,
        "sparklineStrokeColor": "#7c3aed",
        "sparklineAreaColor": "rgba(124,58,237,0.18)",
        "trendDisplay": "percent",
        "showTrendIndicator": true,
        "shouldAbbreviateMajorValue": true,
        "shouldAbbreviateTrendValue": true,
        "backgroundColor": "#ffffff"
      }
    },
    "viz_ov_wired_healthy": {
      "type": "splunk.singlevalue",
      "title": "Healthy Wired Clients",
      "description": "Wired clients currently in healthy status.",
      "dataSources": {
        "primary": "ds_wired_trend_24h"
      },
      "options": {
        "majorValue": "> primary | seriesByName('Healthy') | lastPoint()",
        "majorColor": "#16a34a",
        "majorFontSize": 38,
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "showSparklineTooltip": true,
        "sparklineStrokeColor": "#2563eb",
        "sparklineAreaColor": "rgba(37,99,235,0.18)",
        "trendDisplay": "percent",
        "showTrendIndicator": true,
        "shouldAbbreviateMajorValue": true,
        "shouldAbbreviateTrendValue": true,
        "backgroundColor": "#ffffff"
      }
    },
    "viz_ov_wireless_trend": {
      "type": "splunk.area",
      "title": "Wireless Client Trend",
      "description": "Stacked wireless client count with health score and 80/95 threshold overlays.",
      "dataSources": {
        "primary": "ds_mod_wireless_client_trend_health"
      },
      "options": {
        "backgroundColor": "#ffffff",
        "nullValueDisplay": "zero",
        "showYMajorGridLines": true,
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "stackMode": "stacked",
        "seriesColorsByField": {
          "Healthy": "#16a34a",
          "Fair": "#eab308",
          "Poor": "#dc2626",
          "No Data": "#94a3b8",
          "Wireless Health": "#2563eb",
          "Warning Threshold": "#eab308",
          "Healthy Threshold": "#16a34a"
        },
        "overlayFields": [
          "Wireless Health",
          "Warning Threshold",
          "Healthy Threshold"
        ],
        "showOverlayY2Axis": true,
        "yAxisTitleText": "Clients",
        "y2AxisTitleText": "Health %"
      }
    },
    "viz_ov_wired_trend": {
      "type": "splunk.area",
      "title": "Wired Client Trend",
      "description": "Stacked wired client count with health score and 80/95 threshold overlays.",
      "dataSources": {
        "primary": "ds_mod_wired_client_trend_health"
      },
      "options": {
        "backgroundColor": "#ffffff",
        "nullValueDisplay": "zero",
        "showYMajorGridLines": true,
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "stackMode": "stacked",
        "seriesColorsByField": {
          "Healthy": "#16a34a",
          "Fair": "#eab308",
          "Poor": "#dc2626",
          "No Data": "#94a3b8",
          "Wired Health": "#7c3aed",
          "Warning Threshold": "#eab308",
          "Healthy Threshold": "#16a34a"
        },
        "overlayFields": [
          "Wired Health",
          "Warning Threshold",
          "Healthy Threshold"
        ],
        "showOverlayY2Axis": true,
        "yAxisTitleText": "Clients",
        "y2AxisTitleText": "Health %"
      }
    },
    "viz_ov_ssid_bar": {
      "type": "splunk.bar",
      "title": "Client Count per SSID",
      "description": "Wireless client distribution by SSID for the selected time range.",
      "dataSources": {
        "primary": "ds_cs_by_ssid"
      },
      "options": {
        "backgroundColor": "#ffffff",
        "dataValuesDisplay": "all",
        "legendDisplay": "off",
        "showYMajorGridLines": true,
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "seriesColors": [
          "#2563eb"
        ],
        "xAxisTitleText": "SSID",
        "yAxisTitleText": "Clients"
      }
    },
    "viz_ov_week_line": {
      "type": "splunk.line",
      "title": "Past Week - Client Trends",
      "description": "Wireless and wired client counts over the last 7 days.",
      "dataSources": {
        "primary": "ds_mod_past_week_client_trends"
      },
      "options": {
        "backgroundColor": "#ffffff",
        "nullValueDisplay": "connect",
        "markerDisplay": "outlined",
        "showYMajorGridLines": true,
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "seriesColorsByField": {
          "Wireless Clients": "#2563eb",
          "Wired Clients": "#7c3aed"
        },
        "lineWidth": 3
      }
    },
    "viz_ex_ap_health": {
      "type": "splunk.fillergauge",
      "title": "Access Points",
      "description": "Reachable and managed access points as a percentage of total AP inventory.",
      "context": {
        "healthColorRange": [
          {
            "to": 80,
            "value": "#dc2626"
          },
          {
            "from": 80,
            "to": 95,
            "value": "#eab308"
          },
          {
            "from": 95,
            "value": "#16a34a"
          }
        ]
      },
      "dataSources": {
        "primary": "ds_mod_device_health_ap"
      },
      "options": {
        "value": "> primary | seriesByName('health_pct') | lastPoint()",
        "valueDisplay": "percentage",
        "labelDisplay": "percentage",
        "orientation": "horizontal",
        "gaugeColor": "> primary | seriesByName('health_pct') | lastPoint() | rangeValue(healthColorRange)",
        "backgroundColor": "#ffffff"
      }
    },
    "viz_ex_switch_health": {
      "type": "splunk.fillergauge",
      "title": "Switches",
      "description": "Reachable and managed switches as a percentage of total switch inventory.",
      "context": {
        "healthColorRange": [
          {
            "to": 80,
            "value": "#dc2626"
          },
          {
            "from": 80,
            "to": 95,
            "value": "#eab308"
          },
          {
            "from": 95,
            "value": "#16a34a"
          }
        ]
      },
      "dataSources": {
        "primary": "ds_mod_device_health_switches"
      },
      "options": {
        "value": "> primary | seriesByName('health_pct') | lastPoint()",
        "valueDisplay": "percentage",
        "labelDisplay": "percentage",
        "orientation": "horizontal",
        "gaugeColor": "> primary | seriesByName('health_pct') | lastPoint() | rangeValue(healthColorRange)",
        "backgroundColor": "#ffffff"
      }
    },
    "viz_ex_router_health": {
      "type": "splunk.fillergauge",
      "title": "Routers",
      "description": "Reachable and managed routers as a percentage of total router inventory.",
      "context": {
        "healthColorRange": [
          {
            "to": 80,
            "value": "#dc2626"
          },
          {
            "from": 80,
            "to": 95,
            "value": "#eab308"
          },
          {
            "from": 95,
            "value": "#16a34a"
          }
        ]
      },
      "dataSources": {
        "primary": "ds_mod_device_health_routers"
      },
      "options": {
        "value": "> primary | seriesByName('health_pct') | lastPoint()",
        "valueDisplay": "percentage",
        "labelDisplay": "percentage",
        "orientation": "horizontal",
        "gaugeColor": "> primary | seriesByName('health_pct') | lastPoint() | rangeValue(healthColorRange)",
        "backgroundColor": "#ffffff"
      }
    },
    "viz_ex_firewall_health": {
      "type": "splunk.fillergauge",
      "title": "Firewalls",
      "description": "Reachable and managed firewalls as a percentage of total firewall inventory.",
      "context": {
        "healthColorRange": [
          {
            "to": 80,
            "value": "#dc2626"
          },
          {
            "from": 80,
            "to": 95,
            "value": "#eab308"
          },
          {
            "from": 95,
            "value": "#16a34a"
          }
        ]
      },
      "dataSources": {
        "primary": "ds_mod_device_health_firewalls"
      },
      "options": {
        "value": "> primary | seriesByName('health_pct') | lastPoint()",
        "valueDisplay": "percentage",
        "labelDisplay": "percentage",
        "orientation": "horizontal",
        "gaugeColor": "> primary | seriesByName('health_pct') | lastPoint() | rangeValue(healthColorRange)",
        "backgroundColor": "#ffffff"
      }
    },
    "viz_ex_device_health_distribution": {
      "type": "splunk.bar",
      "title": "Device Health Distribution",
      "description": "Fleet-wide healthy, fair, and poor device distribution.",
      "dataSources": {
        "primary": "ds_mod_device_health_distribution"
      },
      "options": {
        "backgroundColor": "#ffffff",
        "dataValuesDisplay": "all",
        "legendDisplay": "bottom",
        "showYMajorGridLines": true,
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "orientation": "horizontal",
        "stackMode": "stacked",
        "seriesColorsByField": {
          "Healthy": "#16a34a",
          "Fair": "#eab308",
          "Poor": "#dc2626"
        }
      }
    },
    "viz_ex_device_inventory": {
      "type": "splunk.bar",
      "title": "Device Inventory",
      "description": "Reachable versus attention-needed devices by network role.",
      "dataSources": {
        "primary": "ds_mod_device_inventory_bar"
      },
      "options": {
        "backgroundColor": "#ffffff",
        "dataValuesDisplay": "all",
        "legendDisplay": "bottom",
        "showYMajorGridLines": true,
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "orientation": "horizontal",
        "stackMode": "stacked",
        "seriesColorsByField": {
          "Healthy": "#16a34a",
          "NeedsAttention": "#dc2626"
        }
      }
    },
    "viz_ex_device_total_radial": {
      "type": "splunk.singlevalueradial",
      "title": "Device Summary - Total",
      "description": "Total discovered network devices, with radial color based on overall device health.",
      "context": {
        "healthColorRange": [
          {
            "to": 80,
            "value": "#dc2626"
          },
          {
            "from": 80,
            "to": 95,
            "value": "#eab308"
          },
          {
            "from": 95,
            "value": "#16a34a"
          }
        ]
      },
      "dataSources": {
        "primary": "ds_mod_device_summary_total"
      },
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "majorColor": "> primary | seriesByName('health_pct') | lastPoint() | rangeValue(healthColorRange)",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "backgroundColor": "#ffffff",
        "shouldAbbreviateMajorValue": true
      }
    },
    "viz_ex_issues_table": {
      "type": "splunk.table",
      "title": "Issues",
      "description": "Critical and warning alerts requiring attention. Select a row to open details.",
      "dataSources": {
        "primary": "ds_mod_exec_issues_table"
      },
      "options": {
        "backgroundColor": "#ffffff",
        "count": 15,
        "fontSize": "small",
        "showInternalFields": false,
        "drilldown": "row",
        "columnFormat": {
          "Severity": {
            "rowBackgroundColors": "> table | seriesByName(\"Severity\") | matchValue(severityColors)",
            "textOverflow": "break-word"
          },
          "Issue": {
            "textOverflow": "break-word"
          },
          "Sites": {
            "textOverflow": "break-word"
          },
          "Devices": {
            "textOverflow": "break-word"
          }
        }
      },
      "context": {
        "severityColors": [
          {
            "match": "Critical",
            "value": "rgba(220,38,38,0.22)"
          },
          {
            "match": "Warning",
            "value": "rgba(234,179,8,0.22)"
          },
          {
            "match": "Notice",
            "value": "rgba(37,99,235,0.12)"
          },
          {
            "match": "Info",
            "value": "rgba(22,163,74,0.12)"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.setToken",
          "options": {
            "tokens": [
              {
                "token": "selected_issue",
                "key": "row.Issue.value"
              },
              {
                "token": "selected_issue_priority",
                "key": "row.Priority.value"
              }
            ]
          }
        }
      ],
      "containerOptions": {
        "visibility": {
          "hideConditions": [
            "condition_issue_selected"
          ]
        }
      }
    },
    "viz_ex_issue_detail_modal": {
      "type": "splunk.table",
      "title": "Issue Detail",
      "description": "Row-click detail view for the selected active issue.",
      "dataSources": {
        "primary": "ds_mod_selected_issue_detail"
      },
      "options": {
        "backgroundColor": "#ffffff",
        "count": 10,
        "fontSize": "small",
        "showInternalFields": false,
        "drilldown": "none"
      },
      "containerOptions": {
        "visibility": {
          "showConditions": [
            "condition_issue_selected"
          ]
        }
      }
    },
    "viz_client_health_score": {
      "type": "splunk.singlevalue",
      "title": "Active Client Score",
      "description": "Average client health score across wired and wireless clients.",
      "dataSources": {
        "primary": "ds_kpi_cs_health"
      },
      "options": {
        "majorValue": "> primary | seriesByName('Client Health Score') | lastPoint()",
        "majorColor": "> majorValue | rangeValue(healthColorRange)",
        "majorFontSize": 38,
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "showSparklineTooltip": true,
        "sparklineStrokeColor": "> majorValue | rangeValue(healthColorRange)",
        "sparklineAreaColor": "> majorValue | rangeValue(healthColorRange)",
        "trendDisplay": "percent",
        "showTrendIndicator": true,
        "unit": "%",
        "shouldAbbreviateMajorValue": true,
        "shouldAbbreviateTrendValue": true,
        "backgroundColor": "#ffffff"
      },
      "context": {
        "healthColorRange": [
          {
            "to": 80,
            "value": "#dc2626"
          },
          {
            "from": 80,
            "to": 95,
            "value": "#eab308"
          },
          {
            "from": 95,
            "value": "#16a34a"
          }
        ]
      }
    },
    "viz_client_total": {
      "type": "splunk.singlevalue",
      "title": "Total Active Clients",
      "description": "Total unique connected clients in the selected time range.",
      "dataSources": {
        "primary": "ds_kpi_cs_total"
      },
      "options": {
        "majorValue": "> primary | seriesByName('Total Connected Clients') | lastPoint()",
        "majorColor": "#111827",
