        "query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRED\"\n| stats latest(scoreValue) as sv, latest(clientCount) as total by scoreType\n| eval health=round(sv)\n| stats sum(eval(if(scoreType==\"ALL\", total, 0))) as total, avg(eval(if(scoreType==\"ALL\", health, null()))) as health, sum(eval(if(scoreType==\"GOOD\", total, 0))) as healthy, sum(eval(if(scoreType==\"FAIR\", total, 0))) as active, sum(eval(if(scoreType==\"POOR\", total, 0))) as inactive, sum(eval(if(scoreType==\"IDLE\" OR scoreType==\"NODATA\", total, 0))) as new_clients\n| eval health=round(health)",
